class PatientDashboard extends ConsumerStatefulWidget{const PatientDashboard({required this.user,super.key});final AppUser user;@override ConsumerState<PatientDashboard> createState()=>_PatientDashboardState();}
class _PatientDashboardState extends ConsumerState<PatientDashboard>{int index=0;@override Widget build(BuildContext c){final pages=[_PatientHome(user:widget.user),const _Doctors(),const _PatientAppointments(),const _Prescriptions(),const _PatientProfile()];return Scaffold(backgroundColor:AppTheme.background,body:SafeArea(child:IndexedStack(index:index,children:pages)),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),height:76,destinations:const[NavigationDestination(icon:Icon(Icons.home_rounded),label:'الرئيسية'),NavigationDestination(icon:Icon(Icons.medical_services_rounded),label:'الأطباء'),NavigationDestination(icon:Icon(Icons.calendar_month_rounded),label:'مواعيدي'),NavigationDestination(icon:Icon(Icons.receipt_long_rounded),label:'الوصفات'),NavigationDestination(icon:Icon(Icons.person_rounded),label:'حسابي')]));}}
class _PatientHome extends ConsumerWidget{const _PatientHome({required this.user});final AppUser user;@override Widget build(BuildContext c,WidgetRef ref){final ap=ref.watch(appointmentsProvider);return RefreshIndicator(onRefresh:()async{ref.invalidate(appointmentsProvider);},child:ListView(padding:const EdgeInsets.fromLTRB(20,18,20,110),children:[Text('أهلاً ${user.fullName} 👋',style:Theme.of(c).textTheme.headlineSmall),const SizedBox(height:5),const Text('اعتنِ بصحتك، ونحن نهتم بالباقي.',style:TextStyle(color:AppTheme.textSecondary)),const SizedBox(height:20),Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:AppTheme.heroGradient,borderRadius:BorderRadius.circular(30),boxShadow:AppTheme.shadowElevated),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.favorite_rounded,color:Colors.white,size:34),SizedBox(height:18),Text('احجز موعدك بسهولة',style:TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.w800)),SizedBox(height:6),Text('اختر الطبيب ثم تابع دورك وموعدك من مكان واحد.',style:TextStyle(color:Colors.white70,height:1.5))]),),const SizedBox(height:22),Text('مواعيدك القادمة',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:10),ap.when(data:(x)=>x.isEmpty?const _PatientEmpty():Column(children:x.take(4).map((a)=>_PatientAppointment(a:a)).toList()),loading:()=>const CircularProgressIndicator(),error:(e,_)=>Text('تعذر التحميل: $e'))]));}}
class _Doctors extends ConsumerStatefulWidget{const _Doctors();@override ConsumerState<_Doctors> createState()=>_DoctorsState();}
class _DoctorsState extends ConsumerState<_Doctors>{final q=TextEditingController();@override void dispose(){q.dispose();super.dispose();}@override Widget build(BuildContext c){final d=ref.watch(doctorsProvider);return Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,18,20,10),child:TextField(controller:q,onChanged:(_)=>setState((){}),decoration:InputDecoration(hintText:'ابحث عن طبيب أو اختصاص',prefixIcon:const Icon(Icons.search_rounded),filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:BorderSide.none)))),Expanded(child:d.when(data:(items){final s=q.text.trim();final list=s.isEmpty?items:items.where((x)=>('${x.name} ${x.specialty} ${x.address}').contains(s)).toList();return ListView.builder(padding:const EdgeInsets.fromLTRB(20,4,20,100),itemCount:list.length,itemBuilder:(c,i)=>_DoctorTile(d:list[i]));},loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('تعذر تحميل الأطباء'))))]);}}
class _DoctorTile extends StatelessWidget{const _DoctorTile({required this.d});final DoctorCardData d;@override Widget build(BuildContext c)=>Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(22),boxShadow:AppTheme.shadowCard),child:Row(children:[CircleAvatar(radius:28,backgroundColor:AppTheme.primary.withOpacity(.1),backgroundImage:d.photoUrl!=null?NetworkImage(d.photoUrl!):null,child:d.photoUrl==null?const Icon(Icons.person_rounded,color:AppTheme.primary):null),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('د. ${d.name}',style:const TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:3),Text(d.specialty,style:const TextStyle(color:AppTheme.textSecondary)),const SizedBox(height:7),Row(children:[const Icon(Icons.star_rounded,color:Color(0xFFF59E0B),size:16),Text(' ${d.rating.toStringAsFixed(1)}  •  ${d.address}',maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:11,color:AppTheme.textSecondary))])])),Text('${d.fee.toStringAsFixed(0)} د.ع',style:const TextStyle(color:AppTheme.primary,fontWeight:FontWeight.w800))]));}
class _PatientAppointments extends ConsumerWidget{const _PatientAppointments();@override Widget build(BuildContext c,WidgetRef ref){final a=ref.watch(appointmentsProvider);return _PPage(title:'مواعيدي',child:a.when(data:(x)=>ListView(padding:const EdgeInsets.all(20),children:x.map((v)=>_PatientAppointment(a:v)).toList()),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Text('$e')));}}
class _Prescriptions extends ConsumerWidget{const _Prescriptions();@override Widget build(BuildContext c,WidgetRef ref){final p=ref.watch(prescriptionsProvider);return _PPage(title:'الوصفات الطبية',child:p.when(data:(x)=>ListView(padding:const EdgeInsets.all(20),children:x.isEmpty?[const _PatientEmpty()]:x.map((v)=>Container(margin:const EdgeInsets.only(bottom:12),padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20)),child:Text((v['diagnosis']??'وصفة طبية').toString(),style:const TextStyle(fontWeight:FontWeight.w700)))).toList()),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Text('$e')));}}
class _PatientProfile extends ConsumerWidget{const _PatientProfile();@override Widget build(BuildContext c,WidgetRef ref)=>_PPage(title:'حسابي',child:ListView(padding:const EdgeInsets.all(20),children:[ListTile(tileColor:Colors.white,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18)),leading:const Icon(Icons.logout_rounded),title:const Text('تسجيل الخروج'),onTap:()=>ref.read(authProvider.notifier).signOut())]));}
class _PPage extends StatelessWidget{const _PPage({required this.title,required this.child});final String title;final Widget child;@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,20,20,8),child:Align(alignment:Alignment.centerRight,child:Text(title,style:Theme.of(c).textTheme.headlineSmall))),Expanded(child:child)]);}
class _PatientAppointment extends StatelessWidget{const _PatientAppointment({required this.a});final Appointment a;@override Widget build(BuildContext c)=>Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(20)),child:Row(children:[Container(width:48,height:48,alignment:Alignment.center,decoration:BoxDecoration(color:AppTheme.primary.withOpacity(.1),borderRadius:BorderRadius.circular(14)),child:Text('#${a.queueNumber}',style:const TextStyle(color:AppTheme.primary,fontWeight:FontWeight.w800))),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(a.doctorName??'الطبيب',style:const TextStyle(fontWeight:FontWeight.w800)),Text(a.doctorSpecialty??'',style:const TextStyle(color:AppTheme.textSecondary,fontSize:12))])),Text(a.patientsAhead==0?'دورك قريب':'قبلك ${a.patientsAhead}',style:const TextStyle(color:AppTheme.primary,fontWeight:FontWeight.w700,fontSize:12))]));}
